    function __ESBMC_assume(bool) internal pure {}

    function run(address u, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint before = c.getBalance(u); if (__ESBMC_reverted()) return;
        uint ret = c.getBalance(u); if (__ESBMC_reverted()) return;
        uint after_ = c.getBalance(u); if (__ESBMC_reverted()) return;
        assert(ret == before && after_ == before);
    }

    receive() external payable {}
